SELECT p.id, p.user_id, p.category_id, p.title, p.content, p.view_count, p.like_count, p.comment_count, p.cover_url, p.top, p.status, p.is_featured, p.create_time, p.update_time, u.username, u.nickname, u.avatar, c.name AS category_name FROM post p LEFT JOIN user u ON p.user_id = u.id LEFT JOIN category c ON p.category_id = c.id WHERE p.deleted = 0 AND p.status = 0
AND p.category_id = #{categoryId}
ORDER BY p.top DESC, p.create_time DESC

SELECT p.id, p.user_id, p.category_id, p.title, p.content, p.view_count, p.like_count, p.comment_count, p.cover_url, p.top, p.status, p.is_featured, p.create_time, p.update_time, u.username, u.nickname, u.avatar, c.name AS category_name FROM post p LEFT JOIN user u ON p.user_id = u.id LEFT JOIN category c ON p.category_id = c.id WHERE p.deleted = 0 AND p.status = 0
AND p.category_id = #{categoryId}
ORDER BY p.top DESC, p.view_count DESC, p.create_time DESC

SELECT p.id, p.user_id, p.category_id, p.title, p.content, p.view_count, p.like_count, p.comment_count, p.cover_url, p.top, p.status, p.is_featured, p.create_time, p.update_time, u.username, u.nickname, u.avatar, c.name AS category_name FROM post p LEFT JOIN user u ON p.user_id = u.id LEFT JOIN category c ON p.category_id = c.id WHERE p.deleted = 0 AND p.status = 0 AND p.user_id IN ( SELECT followee_id FROM user_follow WHERE follower_id = #{currentUserId} )
AND p.category_id = #{categoryId}
ORDER BY p.top DESC, p.create_time DESC

